CREATE TABLE `users` (`id` uuid,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`username` text,`full_name` varchar(254),`email` varchar(254),`password` varchar(60),`generation` integer,`is_admin` numeric,`enabled` numeric,PRIMARY KEY (`id`),CONSTRAINT `uni_users_email` UNIQUE (`email`));
CREATE TABLE `github_endpoints` (`name` varchar(64) collate nocase,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`endpoint_type` text,`tools_metadata_url` text collate nocase,`use_internal_tools_metadata` numeric,`description` text,`api_base_url` text collate nocase,`upload_base_url` text collate nocase,`base_url` text collate nocase,`ca_cert_bundle` longblob,PRIMARY KEY (`name`));
CREATE TABLE `github_credentials` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`name` varchar(64) collate nocase,`user_id` uuid,`description` text,`auth_type` text,`payload` longblob,`endpoint_name` varchar(64) collate nocase,CONSTRAINT `fk_github_credentials_endpoint` FOREIGN KEY (`endpoint_name`) REFERENCES `github_endpoints`(`name`),CONSTRAINT `fk_github_credentials_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`));
CREATE TABLE `gitea_credentials` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`name` varchar(64) collate nocase,`user_id` uuid,`description` text,`auth_type` text,`payload` longblob,`endpoint_name` varchar(64) collate nocase,CONSTRAINT `fk_gitea_credentials_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`),CONSTRAINT `fk_gitea_credentials_endpoint` FOREIGN KEY (`endpoint_name`) REFERENCES `github_endpoints`(`name`));
CREATE TABLE `tags` (`id` uuid,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`name` varchar(64),PRIMARY KEY (`id`));
CREATE TABLE `enterprises` (`id` uuid,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`credentials_id` integer,`pool_manager_running` numeric,`pool_manager_failure_reason` text,`name` text,`webhook_secret` blob,`pool_balancer_type` varchar(64),`agent_mode` numeric,`endpoint_name` varchar(64) collate nocase,PRIMARY KEY (`id`),CONSTRAINT `fk_enterprises_endpoint` FOREIGN KEY (`endpoint_name`) REFERENCES `github_endpoints`(`name`) ON DELETE SET NULL,CONSTRAINT `fk_github_credentials_enterprises` FOREIGN KEY (`credentials_id`) REFERENCES `github_credentials`(`id`));
CREATE TABLE `templates` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`name` varchar(128),`user_id` uuid,`description` text,`os_type` varchar(32),`forge_type` varchar(32),`data` longblob,CONSTRAINT `fk_templates_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`));
CREATE TABLE `repositories` (`id` uuid,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`credentials_id` integer,`gitea_credentials_id` integer,`pool_manager_running` numeric,`pool_manager_failure_reason` text,`owner` text,`name` text,`webhook_secret` blob,`pool_balancer_type` varchar(64),`agent_mode` numeric,`endpoint_name` varchar(64) collate nocase,PRIMARY KEY (`id`),CONSTRAINT `fk_repositories_endpoint` FOREIGN KEY (`endpoint_name`) REFERENCES `github_endpoints`(`name`) ON DELETE SET NULL,CONSTRAINT `fk_github_credentials_repositories` FOREIGN KEY (`credentials_id`) REFERENCES `github_credentials`(`id`),CONSTRAINT `fk_gitea_credentials_repositories` FOREIGN KEY (`gitea_credentials_id`) REFERENCES `gitea_credentials`(`id`));
CREATE TABLE `organizations` (`id` uuid,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`credentials_id` integer,`gitea_credentials_id` integer,`pool_manager_running` numeric,`pool_manager_failure_reason` text,`name` text,`webhook_secret` blob,`pool_balancer_type` varchar(64),`agent_mode` numeric,`endpoint_name` varchar(64) collate nocase,PRIMARY KEY (`id`),CONSTRAINT `fk_gitea_credentials_organizations` FOREIGN KEY (`gitea_credentials_id`) REFERENCES `gitea_credentials`(`id`),CONSTRAINT `fk_github_credentials_organizations` FOREIGN KEY (`credentials_id`) REFERENCES `github_credentials`(`id`),CONSTRAINT `fk_organizations_endpoint` FOREIGN KEY (`endpoint_name`) REFERENCES `github_endpoints`(`name`) ON DELETE SET NULL);
CREATE TABLE `scale_sets` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`scale_set_id` integer,`name` text,`git_hub_runner_group` text,`disable_update` numeric,`state` text,`extended_state` text,`provider_name` text,`runner_prefix` text,`max_runners` integer,`min_idle_runners` integer,`runner_bootstrap_timeout` integer,`image` text,`flavor` text,`os_type` text,`os_arch` text,`enabled` numeric,`last_message_id` integer,`desired_runner_count` integer,`extra_specs` JSON,`enable_shell` numeric,`generation` integer,`repo_id` uuid,`org_id` uuid,`enterprise_id` uuid,`template_id` integer,CONSTRAINT `fk_enterprises_scale_set` FOREIGN KEY (`enterprise_id`) REFERENCES `enterprises`(`id`),CONSTRAINT `fk_templates_scale_sets` FOREIGN KEY (`template_id`) REFERENCES `templates`(`id`),CONSTRAINT `fk_repositories_scale_sets` FOREIGN KEY (`repo_id`) REFERENCES `repositories`(`id`),CONSTRAINT `fk_organizations_scale_set` FOREIGN KEY (`org_id`) REFERENCES `organizations`(`id`));
CREATE TABLE `scaleset_tags` (`scale_set_id` integer,`tag_id` uuid,PRIMARY KEY (`scale_set_id`,`tag_id`),CONSTRAINT `fk_scaleset_tags_scale_set` FOREIGN KEY (`scale_set_id`) REFERENCES `scale_sets`(`id`) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT `fk_scaleset_tags_tag` FOREIGN KEY (`tag_id`) REFERENCES `tags`(`id`) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE `pools` (`id` uuid,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`provider_name` text,`runner_prefix` text,`max_runners` integer,`min_idle_runners` integer,`runner_bootstrap_timeout` integer,`image` text,`flavor` text,`os_type` text,`os_arch` text,`enabled` numeric,`extra_specs` JSON,`git_hub_runner_group` text,`enable_shell` numeric,`generation` integer,`repo_id` uuid,`org_id` uuid,`enterprise_id` uuid,`template_id` integer,`priority` integer,PRIMARY KEY (`id`),CONSTRAINT `fk_repositories_pools` FOREIGN KEY (`repo_id`) REFERENCES `repositories`(`id`),CONSTRAINT `fk_organizations_pools` FOREIGN KEY (`org_id`) REFERENCES `organizations`(`id`),CONSTRAINT `fk_templates_pools` FOREIGN KEY (`template_id`) REFERENCES `templates`(`id`),CONSTRAINT `fk_enterprises_pools` FOREIGN KEY (`enterprise_id`) REFERENCES `enterprises`(`id`));
